body.script:
          const gameDatabase = [
            { "id": "2048", "title": "2048", "thumbUrl": "https://media-amazon.com", "playUrl": "https://jsdelivr.net" },
            { "id": "bloons", "title": "bloons", "thumbUrl": "https://bloonswiki.com", "playUrl": "https://jsdelivr.net" },
            { "id": "moto-x3m", "title": "moto x3m", "thumbUrl": "", "playUrl": "https://jsdelivr.net" }
          ];

          const navHome = document.getElementById('nav-home');
          const navGames = document.getElementById('nav-games');
          const navSettings = document.getElementById('nav-settings');
          const panelHome = document.getElementById('panel-home');
          const panelGames = document.getElementById('panel-games');
          const panelSettings = document.getElementById('panel-settings');
          const gamesGrid = document.getElementById('games-grid-container');
          const themeSelector = document.getElementById('theme-selector');
          const launchSelector = document.getElementById('launch-behavior');
          const gameViewport = document.getElementById('game-viewport');
          const gameFrame = document.getElementById('game-frame');
          const closeGameBtn = document.getElementById('close-game-btn');

          function switchPanel(activeButton, activePanel) {
            [navHome, navGames, navSettings].forEach(btn => btn.classList.remove('active'));
            [panelHome, panelGames, panelSettings].forEach(pnl => pnl.classList.remove('open'));
            activeButton.classList.add('active');
            activePanel.classList.add('open');
          }

          navHome.addEventListener('click', () => switchPanel(navHome, panelHome));
          navGames.addEventListener('click', () => { switchPanel(navGames, panelGames); renderGameLibrary(); });
          navSettings.addEventListener('click', () => switchPanel(navSettings, panelSettings));

          themeSelector.addEventListener('change', (e) => {
            document.body.className = '';
            if(e.target.value !== 'default') document.body.classList.add('theme-' + e.target.value);
          });

          function renderGameLibrary() {
            gamesGrid.innerHTML = '';
            gameDatabase.forEach(game => {
              const card = document.createElement('div');
              card.className = 'game-card';
              const thumb = document.createElement('div');
              thumb.className = 'game-thumb';
              if(game.thumbUrl) thumb.style.backgroundImage = "url('" + game.thumbUrl + "')";
              else thumb.textContent = game.title.slice(0,2).toUpperCase();
              
              const info = document.createElement('div');
              info.className = 'game-info';
              info.innerHTML = '<div class="game-title">' + game.title + '</div>';
              
              card.appendChild(thumb);
              card.appendChild(info);
              card.addEventListener('click', () => {
                if(launchSelector.value === 'tab') window.open(game.playUrl, '_blank');
                else { gameFrame.src = game.playUrl; gameViewport.classList.add('open'); }
              });
              gamesGrid.appendChild(card);
            });
          }

          closeGameBtn.addEventListener('click', () => { gameViewport.classList.remove('open'); gameFrame.src = 'about:blank'; });
